    private static final class Limited extends ByteArrayOutputStream{final int limit;Limited(int limit){this.limit=limit;}synchronized void wipe(){Arrays.fill(buf,(byte)0);reset();}@Override public synchronized void write(byte[]bytes,int offset,int length){PreparationContracts.require(length<=limit-count,ContextAcquisition.Reason.OUTPUT_LIMIT);super.write(bytes,offset,length);}@Override public synchronized void write(int value){PreparationContracts.require(count<limit,ContextAcquisition.Reason.OUTPUT_LIMIT);super.write(value);}}
